// Merge Grok (narrative) with the TradingView scanner (ground truth prices).
// Output: JSONL lines, one per name. Prices ALWAYS come from the scanner.
const out = [];
const CAT = new Set(['acquisition','merger','earnings','guidance','fda','trial','offering','halt','downgrade','guidance-cut','spin','dividend','other']);

const ts = $now.setZone('America/New_York').toFormat("yyyy-MM-dd'T'HH:mm:ssxxx");
const date = ts.slice(0, 10);

// ---- scanner rows -> map by ticker
const tvRows = [];
try {
  const j = $input.all().find(n => n.json && Array.isArray(n.json.data));
  const d = j ? j.json.data : [];
  for (const r of d) {
    const s = r.d;
    tvRows.push({ ticker: String(s[0]||'').toUpperCase(), name: s[1], close: s[2], change: s[3],
      volume: s[4], rvol10: s[5], market_cap: s[6], premkt_chg: s[7], premkt_vol: s[8],
      premkt_px: s[9], halted: s[10], exchange: s[11] });
  }
} catch (e) {}
const tv = Object.fromEntries(tvRows.map(r => [r.ticker, r]));

// ---- grok lines -> records
const grok = [];
try {
  const g = $input.all().find(n => n.json && n.json.choices);
  const text = g ? (g.json.choices[0].message.content || '') : '';
  for (const line of text.split('\n')) {
    const m = line.match(/\{[^{}]*\}/);
    if (!m) continue;
    try {
      const r = JSON.parse(m[0]);
      if (!r.ticker) continue;
      grok.push(r);
    } catch (e) {}
  }
} catch (e) {}

const seen = new Set();
for (const g of grok) {
  const t = String(g.ticker).toUpperCase();
  if (seen.has(t)) continue;
  seen.add(t);
  const s = tv[t];
  let pct = g.pct, conf = g.conf || 'medium';
  if (s && typeof s.premkt_chg === 'number') {
    if (typeof pct === 'number' && Math.abs(pct - s.premkt_chg) > 2) conf = 'unverified';
    pct = s.premkt_chg;
  } else { conf = 'unverified'; }
  out.push({ ts, src: 'grok', ticker: t, name: g.name || (s && s.name) || null,
    pct: pct === null || pct === undefined ? null : Number(pct),
    price: (s && s.premkt_px) || g.price || null,
    cat: CAT.has(g.cat) ? g.cat : 'other',
    why: String(g.why || '').slice(0, 200), ref: g.ref || null, conf });
}

// scanner-only rows: a big premarket move with no reason yet is itself information
for (const s of tvRows) {
  if (seen.has(s.ticker)) continue;
  if (typeof s.premkt_chg === 'number' && Math.abs(s.premkt_chg) >= 3 && (s.premkt_vol || 0) > 0) {
    out.push({ ts, src: 'tv', ticker: s.ticker, name: s.name, pct: s.premkt_chg,
      price: s.premkt_px, cat: 'other', why: null, ref: null, conf: 'low',
      halted: s.halted === true });
  }
}

return out.map(o => ({ json: o }));
